import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_13/projects/contamcal-irt-calibration/logs/workers/worker_ops_cross_family_irt_j16_retry_20260517T121027.log') as f:
    lines = f.readlines()

# Show all lines from 15 onwards
for i in range(15, len(lines)):
    line = lines[i].strip()
    if not line: continue
    try:
        d = json.loads(line)
        t = d.get('type', '?')
        st = d.get('subtype', '')
        if t == 'assistant':
            for block in d.get('message', {}).get('content', []):
                if block.get('type') == 'text':
                    print(f'[{i}] ASSISTANT: {block[\"text\"][:500]}')
                elif block.get('type') == 'tool_use':
                    print(f'[{i}] TOOL_CALL: {block.get(\"name\",\"?\")}')
        elif t == 'user':
            # tool results
            msg = d.get('message', {})
            content = msg.get('content', [])
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type') == 'tool_result':
                        result_text = str(c.get('content', ''))[:300]
                        print(f'[{i}] TOOL_RESULT: {result_text}')
        else:
            print(f'[{i}] {t}/{st}: {str(d)[:200]}')
    except:
        print(f'[{i}] RAW: {lines[i][:200]}')
